{"files":[{"path":"lib/lore/chips.ts","content":"import type { FilterChip, FilterPredicate } from "@lore/core";
import { PROFILE_FIELDS } from "./fields";

/** Pure chip/label helpers shared by server compiler and client UI. */

export const FIELD_LABELS: Record<string, string> = Object.fromEntries(
  PROFILE_FIELDS.map((f) => [
    f.name,
    f.name
      .split("_")
      .map((w) => w[0]!.toUpperCase() + w.slice(1))
      .join(" "),
  ]),
);

export function predicateLabel(p: FilterPredicate): string {
  switch (p.kind) {
    case "term":
      return `${FIELD_LABELS[p.field]}: ${p.value}`;
    case "terms":
      return `${FIELD_LABELS[p.field]}: ${p.values.slice(0, 2).join(", ")}${
        p.values.length > 2 ? ` +${p.values.length - 2}` : ""
      }`;
    case "range": {
      const parts: string[] = [];
      if (p.min !== undefined) parts.push(`≥ ${p.min}`);
      if (p.max !== undefined) parts.push(`≤ ${p.max}`);
      return `${FIELD_LABELS[p.field]} ${parts.join(" and ")}`;
    }
    case "exists":
      return `Has ${FIELD_LABELS[p.field]}`;
    case "not":
      return `NOT ${predicateLabel(p.predicate)}`;
    case "geo":
      return `${FIELD_LABELS[p.field]} within ${p.radiusMiles}mi`;
    case "text":
      return `"${p.query}"`;
  }
}

export function assembleChips(
  all: FilterPredicate[],
  any: FilterPredicate[],
): FilterChip[] {
  const chips: FilterChip[] = all.map((p, i) => ({
    id: `all-${i}`,
    label: predicateLabel(p),
    predicates: [i],
    source: "extracted" as const,
    ...(p.kind === "terms" && p.values.length > 2
      ? { expansions: p.values.map(String) }
      : {}),
  }));
  if (any.length > 0) {
    chips.push({
      id: "any-group",
      label: `Any of: ${any.map(predicateLabel).join(" · ")}`,
      predicates: any.map((_, i) => i),
      source: "extracted",
    });
  }
  return chips;
}
"}],"concerns":[],"rationale":"Renamed the exported function buildChips to assembleChips in lib/lore/chips.ts, as requested."}

{"files":[{"path":"lib/password-auth.ts","content":"import { createHash, createHmac, timingSafeEqual } from "node:crypto";

export const PASSWORD_SESSION_COOKIE_NAME = "eve_chat_session";
export const PASSWORD_SESSION_MAX_AGE = 60 * 60 * 24 * 30;

const TOKEN_VERSION = "v1";

export function getChatPassword() {
  return process.env.EVE_CHAT_PASSWORD?.trim() ?? "";
}

export function verifyChatPassword(candidate: string) {
  const expected = getChatPassword();

  if (!expected) {
    return false;
  }

  return timingSafeEqual(hash(candidate), hash(expected));
}

export function makePasswordSessionToken(now = Date.now()) {
  const expiresAt = Math.floor(now / 1000) + PASSWORD_SESSION_MAX_AGE;
  const payload = `${TOKEN_VERSION}.${expiresAt}`;
  const signature = sign(payload);

  return `${payload}.${signature}`;
}

export function verifyPasswordSessionToken(token: string | undefined, now = Date.now()) {
  if (!token) {
    return false;
  }

  const [version, expiresAtRaw, signature, ...extra] = token.split(".");
  const expiresAt = Number(expiresAtRaw);

  if (
    version !== TOKEN_VERSION ||
    !signature ||
    extra.length > 0 ||
    !Number.isSafeInteger(expiresAt) ||
    expiresAt <= Math.floor(now / 1000)
  ) {
    return false;
  }

  const expected = sign(`${version}.${expiresAt}`);

  return timingSafeEqual(hash(signature), hash(expected));
}

export function getPasswordSessionFromHeaders(headers: Headers) {
  const cookieHeader = headers.get("cookie");

  if (!cookieHeader) {
    return false;
  }

  const token = cookieHeader
    .split(";")
    .map((cookie) => cookie.trim().split("="))
    .find(([name]) => name === PASSWORD_SESSION_COOKIE_NAME)?.[1];

  return verifyPasswordSessionToken(token ? decodeURIComponent(token) : undefined);
}

export function hasSameOriginRequest(request: Request) {
  const origin = request.headers.get("origin");
  const publicHost =
    request.headers.get("x-forwarded-host") ??
    request.headers.get("host");

  if (!origin || !publicHost) {
    return false;
  }

  try {
    const originUrl = new URL(origin);
    const forwardedProtocol = request.headers.get("x-forwarded-proto");

    return (
      originUrl.host === publicHost &&
      (!forwardedProtocol || originUrl.protocol === `${forwardedProtocol}:`)
    );
  } catch {
    return false;
  }
}

function hash(value: string) {
  return createHash("sha256").update(value).digest();
}

function sign(payload: string) {
  return createHmac("sha256", getChatPassword()).update(payload).digest("base64url");
}
"}],"concerns":[],"rationale":"Renamed the exported function createPasswordSessionToken to makePasswordSessionToken in lib/password-auth.ts as assigned, without touching other files."}

{"files":[{"path":"lib/lore/adapters.ts","content":"import { ElasticsearchAdapter } from "@lore/adapter-elasticsearch";
import { MysqlAdapter } from "@lore/adapter-mysql";
import type { DataSourceAdapter } from "@lore/core";
import {
  PROFILE_ES_INDEX,
  PROFILE_FIELDS,
  PROFILE_ID_FIELD,
  PROFILE_TABLE,
} from "./fields";

/**
 * Server-side adapter registry. Both backends stay live so the demo can
 * switch between them per request and prove parity; `hybrid` searches ES and
 * hydrates rows from MySQL (source-of-truth pattern).
 */
export type BackendId = "elasticsearch" | "mysql" | "hybrid";

type Row = Record<string, unknown>;

const globals = globalThis as unknown as {
  __loreEs?: ElasticsearchAdapter<Row>;
  __loreMy?: MysqlAdapter<Row>;
};

export function esAdapter(): ElasticsearchAdapter<Row> {
  globals.__loreEs ??= new ElasticsearchAdapter<Row>({
    node: process.env.LORE_ES_URL ?? "http://localhost:9200",
    index: PROFILE_ES_INDEX,
    fields: PROFILE_FIELDS,
    idField: PROFILE_ID_FIELD,
  });
  return globals.__loreEs;
}

export function mysqlAdapter(): MysqlAdapter<Row> {
  globals.__loreMy ??= new MysqlAdapter<Row>({
    uri: process.env.LORE_MYSQL_URL ?? "mysql://root@localhost:3306/lore",
    table: PROFILE_TABLE,
    fields: PROFILE_FIELDS,
    idField: PROFILE_ID_FIELD,
  });
  return globals.__loreMy;
}

/** Hybrid: ES answers search/counts/facets; MySQL hydrates full rows by id. */
class HybridAdapter implements DataSourceAdapter<Row> {
  readonly id = "hybrid:es-search+mysql-hydrate";
  get capabilities() {
    return esAdapter().capabilities;
  }
  fields() {
    return esAdapter().fields();
  }
  count(filter: Parameters<DataSourceAdapter<Row>["count"]>[0]) {
    return esAdapter().count(filter);
  }
  async search(
    ...args: Parameters<DataSourceAdapter<Row>["search"]>
  ): ReturnType<DataSourceAdapter<Row>["search"]> {
    const page = await esAdapter().search(...args);
    const ids = page.rows.map((r) => String(r[PROFILE_ID_FIELD]));
    const hydrated = await mysqlAdapter().hydrate(ids);
    const byId = new Map(hydrated.map((r) => [String(r[PROFILE_ID_FIELD]), r]));
    return {
      ...page,
      rows: page.rows.map((r) => byId.get(String(r[PROFILE_ID_FIELD])) ?? r),
    };
  }
  aggregate(...args: Parameters<DataSourceAdapter<Row>["aggregate"]>) {
    return esAdapter().aggregate(...args);
  }
  hydrate(ids: string[]) {
    return mysqlAdapter().hydrate(ids);
  }
}

const hybrid = new HybridAdapter();

export function adapterForCore(backend: BackendId): DataSourceAdapter<Row> {
  if (backend === "mysql") return mysqlAdapter();
  if (backend === "hybrid") return hybrid;
  return esAdapter();
}
"}],"concerns":[],"rationale":"Renamed the exported function adapterFor to adapterForCore in lib/lore/adapters.ts as instructed."}

{"files":[{"path":"lib/chat/provisional-chat.ts","content":"const PENDING_CHAT_STORAGE_MAX_AGE_MS = 10 * 60 * 1000;
const PENDING_CHAT_STORAGE_PREFIX = "eve-chat-pending:";
const PROVISIONAL_CHAT_ID_PREFIX = "new-";

type StoredPendingChat = {
  readonly createdAt: number;
  readonly pendingUserMessage: string;
  readonly version: 1;
};

export function makeProvisionalChatId() {
  const randomId =
    globalThis.crypto?.randomUUID?.() ??
    `${Date.now()}-${Math.random().toString(36).slice(2)}`;

  return `${PROVISIONAL_CHAT_ID_PREFIX}${randomId}`;
}

export function isProvisionalChatId(chatId: string) {
  return chatId.startsWith(PROVISIONAL_CHAT_ID_PREFIX);
}

export function writePendingChatMessage(chatId: string, message: string) {
  const pendingUserMessage = message.trim();

  if (!pendingUserMessage || typeof window === "undefined") {
    return false;
  }

  try {
    window.sessionStorage.setItem(
      getPendingChatStorageKey(chatId),
      JSON.stringify({
        createdAt: Date.now(),
        pendingUserMessage,
        version: 1,
      } satisfies StoredPendingChat),
    );
    return true;
  } catch {
    return false;
  }
}

export function readPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return null;
  }

  const key = getPendingChatStorageKey(chatId);
  const stored = window.sessionStorage.getItem(key);

  if (!stored) {
    return null;
  }

  try {
    const parsed = JSON.parse(stored) as Partial<StoredPendingChat>;
    const createdAt = Number(parsed.createdAt);
    const pendingUserMessage = parsed.pendingUserMessage?.trim();

    if (
      !pendingUserMessage ||
      !Number.isFinite(createdAt) ||
      Date.now() - createdAt > PENDING_CHAT_STORAGE_MAX_AGE_MS
    ) {
      window.sessionStorage.removeItem(key);
      return null;
    }

    return pendingUserMessage;
  } catch {
    window.sessionStorage.removeItem(key);
    return null;
  }
}

export function clearPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return;
  }

  window.sessionStorage.removeItem(getPendingChatStorageKey(chatId));
}

function getPendingChatStorageKey(chatId: string) {
  return `${PENDING_CHAT_STORAGE_PREFIX}${chatId}`;
}
"}],"concerns":["The caller in app/_components/home-chat-page.tsx still references createProvisionalChatId; this rename alone will break the build until the caller is updated."],"rationale":"Renamed createProvisionalChatId to makeProvisionalChatId in lib/chat/provisional-chat.ts as instructed, leaving all other file contents unchanged."}

{"files":[{"path":"app/actions/chat.ts","content":""use server";

import type { HandleMessageStreamEvent, SessionState } from "eve/client";
import {
  appendChatEvent,
  clearChatPendingMessage,
  createChat,
  deleteChatForUser,
  listChatsByUser,
  markChatPendingMessage,
  saveChatSnapshot,
  saveChatSessionState,
  skipChatAuthorization,
} from "@/lib/db/queries";
import { assertChatMessageLength } from "@/lib/chat/limits";
import { RateLimitError, enforceRateLimit } from "@/lib/rate-limit";
import { getServerViewer } from "@/lib/session";
import { getSetupStatus } from "@/lib/setup";

const SEND_LIMIT = 25;
const SEND_WINDOW_SECONDS = 60 * 60;

export async function createChatAction(input?: { readonly pendingUserMessage?: string }) {
  const viewer = await requireViewer();

  if (input?.pendingUserMessage) {
    assertChatMessageLength(input.pendingUserMessage);
  }

  await enforceRateLimit({
    key: viewer.id,
    limit: SEND_LIMIT,
    prefix: "chat:create",
    windowSeconds: SEND_WINDOW_SECONDS,
  });

  return createChat(viewer.id, {
    pendingUserMessage: input?.pendingUserMessage,
  });
}

export async function checkSendLimitAction(input?: { readonly message?: string }) {
  const viewer = await requireViewer();

  try {
    if (input?.message) {
      assertChatMessageLength(input.message);
    }

    await enforceRateLimit({
      key: viewer.id,
      limit: SEND_LIMIT,
      prefix: "chat:send",
      windowSeconds: SEND_WINDOW_SECONDS,
    });

    return { allowed: true as const };
  } catch (error) {
    if (error instanceof RateLimitError) {
      return {
        allowed: false as const,
        message: error.message,
        retryAfter: error.retryAfter,
      };
    }

    throw error;
  }
}

export async function saveChatSnapshotAction(input: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  const viewer = await requireViewer();

  await saveChatSnapshot({
    chatId: input.chatId,
    events: input.events,
    session: input.session,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function markChatPendingMessageAction(input: {
  readonly chatId: string;
  readonly message: string;
}) {
  const viewer = await requireViewer();

  assertChatMessageLength(input.message);

  return markChatPendingMessage({
    chatId: input.chatId,
    message: input.message,
    userId: viewer.id,
  });
}

export async function clearChatPendingMessageAction(chatId: string) {
  const viewer = await requireViewer();

  await clearChatPendingMessage({
    chatId,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function skipChatAuthorizationAction(input: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  const viewer = await requireViewer();

  return skipChatAuthorization({
    chatId: input.chatId,
    events: input.events,
    session: input.session,
    userId: viewer.id,
  });
}

export async function pushChatEventAction(input: {
  readonly chatId: string;
  readonly event: HandleMessageStreamEvent;
  readonly eventIndex: number;
}) {
  const viewer = await requireViewer();

  await appendChatEvent({
    chatId: input.chatId,
    event: input.event,
    eventIndex: input.eventIndex,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function saveChatSessionStateAction(input: {
  readonly chatId: string;
  readonly session: SessionState;
}) {
  const viewer = await requireViewer();

  await saveChatSessionState({
    chatId: input.chatId,
    session: input.session,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function deleteChatAction(chatId: string) {
  const viewer = await requireViewer();

  await deleteChatForUser(chatId, viewer.id);

  return listChatsByUser(viewer.id);
}

async function requireViewer() {
  const setupStatus = await getSetupStatus();

  if (setupStatus.storageMode !== "database") {
    throw new Error("Database persistence is not enabled.");
  }

  const viewer = await getServerViewer(setupStatus);

  if (!viewer) {
    throw new Error("Sign in to continue.");
  }

  return viewer;
}
"}],"concerns":[],"rationale":"Renamed the exported function appendChatEventAction to pushChatEventAction in app/actions/chat.ts only, leaving all other code unchanged."}

{"files":[{"path":"lib/setup.ts","content":"import type { SetupStatus } from "@/lib/chat/types";
import { isDatabaseConfigured, isDatabaseSchemaReady } from "@/lib/db/client";

const PASSWORD_ENV_KEY = "EVE_CHAT_PASSWORD";
const AUTH_ENV_KEYS = [
  "BETTER_AUTH_SECRET",
  "NEXT_PUBLIC_VERCEL_APP_CLIENT_ID",
  "VERCEL_APP_CLIENT_SECRET",
] as const;

const RATE_LIMIT_ENV_GROUPS = [
  ["UPSTASH_REDIS_REST_URL", "UPSTASH_REDIS_REST_TOKEN"],
  ["KV_REST_API_URL", "KV_REST_API_TOKEN"],
] as const;

function hasEnv(name: string) {
  return Boolean(process.env[name]?.trim());
}

export function isAuthConfigured() {
  return AUTH_ENV_KEYS.every(hasEnv);
}

export function isPasswordConfigured() {
  return Boolean(process.env.EVE_CHAT_PASSWORD?.trim());
}

export function isRateLimitConfigured() {
  return RATE_LIMIT_ENV_GROUPS.some((group) => group.every(hasEnv));
}

export function readInitialSetupStatus(): SetupStatus {
  return createSetupStatus({
    databaseSchemaReady: isDatabaseConfigured(),
  });
}

export async function getSetupStatus(): Promise<SetupStatus> {
  const databaseConfigured = isDatabaseConfigured();
  const fullEnvironmentReady =
    databaseConfigured && isAuthConfigured() && isRateLimitConfigured();
  const databaseSchemaReady = fullEnvironmentReady
    ? await isDatabaseSchemaReady()
    : false;

  return createSetupStatus({ databaseSchemaReady });
}

export async function isAppConfigured() {
  const status = await getSetupStatus();

  return status.appReady;
}

function createSetupStatus({
  databaseSchemaReady,
}: {
  readonly databaseSchemaReady: boolean;
}): SetupStatus {
  const databaseConfigured = isDatabaseConfigured();
  const vercelAuthReady = isAuthConfigured();
  const rateLimitReady = isRateLimitConfigured();
  const databaseReady = databaseConfigured && databaseSchemaReady;
  const fullEnvironmentReady = databaseConfigured && vercelAuthReady && rateLimitReady;
  const passwordReady = isPasswordConfigured();
  const localDevReady = isLocalDevelopment();

  if (fullEnvironmentReady) {
    return {
      appReady: databaseReady,
      authMode: "vercel",
      authReady: vercelAuthReady,
      databaseConfigured,
      databaseReady,
      databaseSchemaReady,
      missing: databaseSchemaReady ? [] : ["database migrations"],
      rateLimitReady,
      storageMode: "database",
    };
  }

  if (passwordReady || localDevReady) {
    return {
      appReady: true,
      authMode: passwordReady ? "password" : "local-dev",
      authReady: true,
      databaseConfigured,
      databaseReady,
      databaseSchemaReady,
      missing: [],
      rateLimitReady,
      storageMode: "browser",
    };
  }

  return {
    appReady: false,
    authMode: "unconfigured",
    authReady: false,
    databaseConfigured,
    databaseReady,
    databaseSchemaReady,
    missing: [
      PASSWORD_ENV_KEY,
      "or DATABASE_URL, Better Auth/Vercel OAuth, and Upstash configuration",
    ],
    rateLimitReady,
    storageMode: "browser",
  };
}

function isLocalDevelopment() {
  return process.env.NODE_ENV === "development" && process.env.VERCEL !== "1";
}
"}],"concerns":[],"rationale":"Renamed the exported function from getInitialSetupStatus to readInitialSetupStatus in lib/setup.ts as instructed."}

