(() => {
  try {
    const loggedIn = document.cookie
      .split("; ")
      .some((cookie) => cookie === ${JSON.stringify(
        `${AUTH_HINT_COOKIE_NAME}=${AUTH_HINT_COOKIE_VALUE}`,
